package com.greenpulse.controller;
import com.greenpulse.common.ApiEnvelope;import com.greenpulse.service.MlIntegrationService;import org.springframework.web.bind.annotation.*;import java.util.*;
import org.springframework.security.access.prepost.PreAuthorize;
@RestController @RequestMapping("/api/v1")
public class MlController {
 private final MlIntegrationService ml;public MlController(MlIntegrationService ml){this.ml=ml;}
 @PostMapping("/predictions/generate/{buildingId}") @PreAuthorize("hasAnyRole('SUPER_ADMIN','ORG_ADMIN','BUILDING_MANAGER','ANALYST')") public ApiEnvelope<?> predict(@PathVariable Long buildingId){return ApiEnvelope.ok("Predictions generated and stored",ml.predict(buildingId));}
 @GetMapping("/predictions/{buildingId}") public ApiEnvelope<?> predictions(@PathVariable Long buildingId){return ApiEnvelope.ok("Stored predictions",ml.predictionList(buildingId).stream().map(p->Map.of("id",p.getId(),"buildingId",p.getBuilding().getId(),"predictionDate",p.getPredictionDate().toString(),"predictedKwh",p.getPredictedKwh(),"modelName",p.getModelName(),"modelVersion",p.getModelVersion())).toList());}
 @GetMapping("/predictions/{buildingId}/summary") public ApiEnvelope<?> summary(@PathVariable Long buildingId){var rows=ml.predictionList(buildingId);return ApiEnvelope.ok("Prediction summary",Map.of("count",rows.size(),"predictions",rows.stream().map(p->Map.of("predictionDate",p.getPredictionDate().toString(),"predictedKwh",p.getPredictedKwh())).toList()));}
 @PostMapping("/anomalies/detect/{buildingId}") @PreAuthorize("hasAnyRole('SUPER_ADMIN','ORG_ADMIN','BUILDING_MANAGER')") public ApiEnvelope<?> detect(@PathVariable Long buildingId){return ApiEnvelope.ok("Anomaly detection complete",ml.detect(buildingId));}
 @GetMapping("/anomalies") public ApiEnvelope<?> anomalies(){return ApiEnvelope.ok("Anomaly alerts",ml.anomalyList().stream().map(a->Map.of("id",a.getId(),"buildingId",a.getBuilding().getId(),"buildingName",a.getBuilding().getName(),"readingDate",a.getReading().getReadingDate().toString(),"anomalyScore",a.getAnomalyScore(),"severity",a.getSeverity(),"description",a.getDescription(),"status",a.getStatus())).toList());}
 @GetMapping("/anomalies/{id}") public ApiEnvelope<?> anomaly(@PathVariable Long id){var a=ml.anomaly(id);return ApiEnvelope.ok("Anomaly alert",Map.of("id",a.getId(),"buildingId",a.getBuilding().getId(),"readingDate",a.getReading().getReadingDate().toString(),"anomalyScore",a.getAnomalyScore(),"severity",a.getSeverity(),"description",a.getDescription(),"status",a.getStatus()));}
 @PutMapping("/anomalies/{id}/status") @PreAuthorize("hasAnyRole('SUPER_ADMIN','ORG_ADMIN','BUILDING_MANAGER')") public ApiEnvelope<?> status(@PathVariable Long id,@RequestBody Map<String,String> body){var a=ml.status(id,body.getOrDefault("status",""));return ApiEnvelope.ok("Anomaly status updated",Map.of("id",a.getId(),"status",a.getStatus()));}
}
